class WFTDownloader(object):
    def __init__(self, wft_address='https://wft.int.net.nokia.com', port='8091', proxies=None,
                 access_key="qa8SJGtOakhrk9Q8kiTQTK2eZEp8TH2tLi3vZJao"):
        """
        :param wft_address: https address
        :param port: port number as string
        :param access_key: an authorization token
        :param proxies: {'http': 'http://10.10.1.10:3128',
                         'https': 'http://proxy-lab.krk-lab.nsn-rdnet.net:8080'}
        """
        requests.packages.urllib3.disable_warnings()

        self.wft_address = wft_address
        self.port = port
        self.proxies = proxies
        self.access_key = access_key

    def download(self, url, json=False, stream=True, user=None, password=None):
        """
        Downloads content of given url.
        :param url: URL address. Required.
        :param json: if set True converts response data to JSON format. Default False.
        :param stream: If set True read data as it arrives, if False data is returned as a single chunk. Default True.
        :param user: user name for authentication.
        :param password: password for authentication.
        """
        self._get_from_url(url=url, json=json, stream=stream, user=user, password=password)

    def download_to_file(self, url, destination_path=None, filename=None, stream=True, user=None, password=None):
        """
        Downloads content of given url.
        :param url: URL address. Required.
        :param destination_path: destination directory for downloaded file.
        :param filename: destination file name. If not specified it's a name from URL. Doesn't work with json=True.
        :param stream: If set True read data as it arrives, if False data is returned as a single chunk. Default True.
        :param user: user name for authentication.
        :param password: password for authentication.
        """
        if filename is None:
            filename = WFTDownloader.get_filename_from_url(url)

        return self._get_from_url_to_file(url=url, destination_path=destination_path, filename=filename, stream=stream,
                                          user=user, password=password)

    def get_build_info(self, build_version):
        """
        Gets information about given build_version
        :param build_version: number of the build. Required.
        :returns build information in JSON format.
        """

        project = WFTDownloader._get_project(build_version)
        component = WFTDownloader._get_component(build_version)

        wft_url = "{}:{}/api/v1/{}/{}/builds/{}.json?access_key={}".format(
            self.wft_address, self.port, project, component, build_version, self.access_key)

        return self._get_from_url(url=wft_url, json=True)

    def get_hub_url(self, hub_version, user='ca_ivk_crt', password='caivkcrt'):
        """
        Gets url to hub config file.
        :param hub_version: version of hub. Required.
        :param user: user name for authentication.
        :param password: pass word for authentication.
        :returns url to download hub config file.
        """

        hub_build = self.get_build_info(hub_version)
        hub_url = hub_build['repository_url']
        if "ASIHUB2.0" in hub_version:
            hub_url = "{}tags/{}/C_Element/SE_ASI/SS_ASIHUB2/Target".format(hub_url, hub_version)
            re_filename = re.compile(r"file\sname=\"(?P<FILENAME>fzhub2-bundle_\d+\.tgz)\"", re.I)
        else:
            hub_url = "{}tags/{}/C_Element/SE_ASI/SS_ASIHUB/Target".format(hub_url, hub_version)
            re_filename = re.compile(r"file\sname=\"(?P<FILENAME>fzhub-bundle_\d+\.tgz)\"", re.I)
        html_target_page = self._get_from_url(hub_url, user=user, password=password).text

        match = re_filename.search(html_target_page)

        if match:
            filename = match.group("FILENAME")
        else:
            raise WFTDownloaderError("Couldn't find a name of hub config file.")

        return hub_url + "/{}".format(filename)

    def get_hub_version(self, build_version, component_name="ASIHUB"):
        """
        Gets version of hub from build information.
        :param build_version: number of the build. Required.
        :param component_name: component name from wft, should equal to ASIHUB/ASIHUB2.0
        :returns version of hub.
        """
        # ASIHUB18.12.R01
        # ASIHUB_RL22R4_22.08.R06
        re_hub_version = \
            re.compile(r"(?P<HUB_VERSION>({}\d+\.\d+\.R\d+)|({}_RL\d+R\d+_\d+\.\d+\.R\d+))".format(component_name,
                                                                                                   component_name))
        build_info = self.get_build_info(build_version=build_version)

        match = re_hub_version.search(build_info['custom_config_spec'])

        if match:
            return match.group("HUB_VERSION")
        else:
            raise WFTDownloaderError("Couldn't get hub version.")

    def get_enb_url(self, build_version):
        """
        Gets url to download eNB build.
        :param build_version: number of the build. Required.
        :returns url to eNB build.
        """

        result = self.get_build_from_storage(build_version)
        release = re.compile(r"^SBTS")
        if release.match(build_version):
            enb_storage_item_title = build_version + "_release_BTSSM_downloadable_A54.zip"
        else:
            enb_storage_item_title = build_version + "_release_BTSSM_downloadable.zip"

        for item in result:
            for storage_item in item["storage"]["storage-items"]:
                if storage_item["title"] == enb_storage_item_title:
                    return storage_item["path"]
        raise WFTDownloaderError("Couldn't get eNB url.")

    def get_build_from_storage(self, build_version, json=True):
        """
        Gets build from storage.
        :param build_version: version of the build. Required.
        :param json: if set True converts response data to JSON format. Default True.
        :return: build.
        """

        project = WFTDownloader._get_project(build_version)
        component = WFTDownloader._get_component(build_version)
        wft_storage_url = "{}:{}/api/v1/{}/{}/builds/{}/storages/results.json?access_key={}".format(
            self.wft_address, self.port, project, component, build_version, self.access_key)

        return self._get_from_url(url=wft_storage_url, json=json)

    @staticmethod
    def get_filename_from_url(url):
        """
        Extracts name of file from URL.
        :param url: URL. Required.
        :return: name of file.
        """
        start_index = url.rindex('/')
        end_index = len(url)
        question_mark = url.rfind('?')
        if question_mark > start_index:
            end_index = question_mark
        return url[start_index + 1:end_index]

    @staticmethod
    def _get_project(build_version):
        """
        Gets project type from build version.
        :param build_version: version of build. Required.
        :return: project type.
        """

        if WFTDownloader._get_component(build_version) == "ASIHUB":
            return "ALL"
        branch = re.match(r"(?P<PROJECT>[^\d]+)", build_version).group("PROJECT")
        project_types = {
            "FL": "LTE:WMP:FDD",
            "FLF": "LTE:FZM:FDD",
            "TLF": "LTE:FZM:TDD",
            "FLC": "LTE:FZC:TDD",
            "SBTS": "SBTS"
        }

        if branch in project_types:
            return project_types[branch]
        else:
            raise InvalidParameterError("got invalid build version while searching for project type.")

    @staticmethod
    def _get_component(build_version):
        """
        Gets build type from build version.
        :param build_version: version of build. Required.
        :return: ENB or ASIHUB.
        """
        if "ASIHUB" in build_version:
            return "ASIHUB"
        if "ENB" in build_version:
            return "ENB"
        else:
            raise InvalidParameterError("got invalid build version while searching for component type.")

    @staticmethod
    def _write_to_file(response, filename, destination_path=None):
        """
        Writes response content to file.
        :param response: response object
        :param filename: name of file you write to
        :param destination_path: destination directory of file
        :return: nothing
        """
        if destination_path:
            filename = "{}/{}".format(destination_path, filename)
        with open(filename, 'wb') as dest_file:
            for chunk in response.iter_content(chunk_size=128):
                dest_file.write(chunk)
        return dest_file

    def _get_from_url(self, url, json=False, stream=True, user=None, password=None):
        """
        Connects to the given URL and downloads its content.
        :param url: URL address. Required.
        :param stream: If set True read data as it arrives, if set False data is returned as a single chunk.
        :param user: user name for authentication.
        :param password: pass word for authentication.
        :return Response object or json
        """
        url_connection = URLConnection(proxies=self.proxies, stream=stream, verify=False, user=user, password=password)
        url_connection.connect()
        try:
            response = url_connection.get(url)
            if response.status_code != 200:
                raise GetFromUrlError("Http response error occurred with status code ", response.status_code)
            if json:
                return response.json()
            else:
                return response
        except RequestException as exception:
            raise GetFromUrlError("Request error occured with exception {}".format(exception))

    def _get_from_url_to_file(self, url, filename, destination_path=None, stream=True, user=None, password=None):
        """
        Connects to the given URL and downloads its content.
        :param url: URL address. Required.
        :param destination_path: destination directory for downloaded file.
        :param filename: destination file name. Doesn't work with json set to True.
        :param stream: If set True read data as it arrives, if set False data is returned as a single chunk.
        :param user: user name for authentication.
        :param password: pass word for authentication.
        :return destination file object
        """
        url_connection = URLConnection(proxies=self.proxies, stream=stream, verify=False, user=user, password=password)
        url_connection.connect()
        try:
            response = url_connection.get(url)
            if response.status_code != 200:
                raise GetFromUrlError("Http response error occurred with status code ", response.status_code)
            destination_file = WFTDownloader._write_to_file(response=response, filename=filename,
                                                            destination_path=destination_path)
            return destination_file
        except RequestException as exception:
            raise GetFromUrlError("Request error occured with exception {}".format(exception))

